from collections import OrderedDict


def lfuCacheGets(capacity, ops):
    val = {}
    freq = {}
    buckets = {}
    min_freq = 0

    def touch(k):
        nonlocal min_freq
        f = freq[k]
        b = buckets[f]
        del b[k]
        if not b:
            del buckets[f]
            if min_freq == f:
                min_freq = f + 1
        freq[k] = f + 1
        buckets.setdefault(f + 1, OrderedDict())[k] = None

    out = []
    for t, k, v in ops:
        if t == 0:
            if k in val:
                touch(k)
                out.append(val[k])
            else:
                out.append(-1)
        elif capacity > 0:
            if k in val:
                val[k] = v
                touch(k)
            else:
                if len(val) == capacity:
                    old, _ = buckets[min_freq].popitem(last=False)
                    if not buckets[min_freq]:
                        del buckets[min_freq]
                    del val[old]
                    del freq[old]
                val[k] = v
                freq[k] = 1
                buckets.setdefault(1, OrderedDict())[k] = None
                min_freq = 1
    return out
